const { execFileSync } = require('child_process');
const fs = require('fs');
const EXE = '/workspace/dataset/test13_executable';
const OUT = '/workspace/probes/draft3-legacy.jsonl';
const pairs = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
let lines = [];
for (const [a, b, label] of pairs) {
  let out = '', code = 0;
  try {
    out = execFileSync(EXE, ['--a', a, '--b', b], { encoding: 'utf8', stdio: ['ignore','pipe','pipe'] });
  } catch (e) {
    out = (e.stdout || '');
    code = (typeof e.status === 'number') ? e.status : -1;
    var stderr = (e.stderr||'');
  }
  lines.push(JSON.stringify({ a, b, out, exit: code }));
  const compact = out.replace(/\n/g, ' | ').trim();
  console.log(`${(label||'').padEnd(38)} :: ${compact}  [exit=${code}]${code!==0 ? ' STDERR:'+((stderr||'').split('\n').filter(Boolean).slice(-1)[0]||'') : ''}`);
}
fs.appendFileSync(OUT, lines.join('\n') + '\n');
console.error(`appended ${lines.length}`);
EOF
